type Copia<T> = { [K in keyof T]: T[K] };

interface Produto {
  id: number;
  nome: string;
  preco: number;
}

type ProdutoCopia = Copia<Produto>;

const p: ProdutoCopia = { id: 1, nome: "Teclado", preco: 49.9 };
console.log(p.nome); // Teclado

const q: ProdutoCopia = {
  id: 2,
  nome: "Rato",
  preco: 19.9,
  // @ts-expect-error a cópia tem exatamente as mesmas chaves do original: stock não existe
  stock: 5,
};
console.log(q.id); // 2

type Dicionario<K extends PropertyKey, V> = { [P in K]: V };

type Idioma = "pt" | "en" | "fr";
type Saudacoes = Dicionario<Idioma, string>;

const saudacoes: Saudacoes = { pt: "Olá", en: "Hello", fr: "Bonjour" };
console.log(saudacoes.fr); // Bonjour

// @ts-expect-error falta a chave fr, que o mapeamento tornou obrigatória
const incompleto: Saudacoes = { pt: "Olá", en: "Hello" };
console.log(incompleto.pt); // Olá

type Coordenadas = { [K in "x" | "y"]: number };
const ponto: Coordenadas = { x: 3, y: 4 };
console.log(ponto.x + ponto.y); // 7

type Contagens = Dicionario<number, string>;
const porIndice: Contagens = { 0: "zero", 1: "um" };
console.log(porIndice[1]); // um

interface Config {
  host: string;
  porta: number;
  ativo: boolean;
}

type EmFabrica<T> = { [K in keyof T]: () => T[K] };
type EmArray<T> = { [K in keyof T]: T[K][] };
type EmPromessa<T> = { [K in keyof T]: Promise<T[K]> };
type TudoTexto<T> = { [K in keyof T]: string };

const fabricas: EmFabrica<Config> = {
  host: () => "localhost",
  porta: () => 8080,
  ativo: () => true,
};
console.log(fabricas.porta()); // 8080

const listas: EmArray<Config> = { host: ["a", "b"], porta: [80, 443], ativo: [true] };
console.log(listas.porta.length); // 2

const texto: TudoTexto<Config> = { host: "localhost", porta: "8080", ativo: "sim" };
console.log(texto.ativo); // sim

const promessas: EmPromessa<Config> = {
  host: Promise.resolve("localhost"),
  porta: Promise.resolve(8080),
  ativo: Promise.resolve(true),
};
promessas.porta.then((valor) => console.log(valor)); // 8080

interface Utilizador {
  readonly id: number;
  nome: string;
  email?: string;
}

type TudoOpcional<T> = { [K in keyof T]?: T[K] };
type TudoObrigatorio<T> = { [K in keyof T]-?: T[K] };
type TudoSoLeitura<T> = { readonly [K in keyof T]: T[K] };
type TudoEscrevivel<T> = { -readonly [K in keyof T]: T[K] };

const parcial: TudoOpcional<Utilizador> = { nome: "Ana" };
console.log(parcial.nome); // Ana

const completo: TudoObrigatorio<Utilizador> = { id: 1, nome: "Ana", email: "ana@exemplo.pt" };
console.log(completo.email.length); // 14

// @ts-expect-error com -? o email deixou de ser opcional e tem de estar presente
const semEmail: TudoObrigatorio<Utilizador> = { id: 2, nome: "Rui" };
console.log(semEmail.nome); // Rui

const fixo: TudoSoLeitura<Utilizador> = { id: 3, nome: "Rui" };
// @ts-expect-error o readonly acrescentado pelo mapeamento impede a reatribuição
fixo.nome = "Rita";

const livre: TudoEscrevivel<Utilizador> = { id: 4, nome: "Rita" };
livre.id = 5;
console.log(livre.id); // 5

interface Pedido {
  readonly id: number;
  cliente: string;
  nota?: string;
}

type Espelho<T> = { [K in keyof T]: T[K] };
type Escrito = { [K in "id" | "cliente" | "nota"]: Pedido[K] };

const homomorfico: Espelho<Pedido> = { id: 1, cliente: "Ana" };
// @ts-expect-error o mapeamento homomórfico preservou o readonly original do id
homomorfico.id = 2;
console.log(homomorfico.cliente); // Ana

const manual: Escrito = { id: 1, cliente: "Ana", nota: undefined };
manual.id = 2;
console.log(manual.id); // 2

type EmCaixa<T> = { [K in keyof T]: { valor: T[K] } };

const caixas: EmCaixa<number[]> = [{ valor: 1 }, { valor: 2 }];
console.log(caixas.length); // 2

const par: EmCaixa<[number, string]> = [{ valor: 1 }, { valor: "a" }];
const comprimento: 2 = par.length;
console.log(comprimento, par[1].valor); // 2 a

interface Registo {
  id: number;
  nome: string;
  ativo: boolean;
  idade: number;
}

type ApenasDoTipo<T, V> = { [K in keyof T as T[K] extends V ? K : never]: T[K] };
type SemEstas<T, K extends keyof T> = { [P in keyof T as P extends K ? never : P]: T[P] };

const numeros: ApenasDoTipo<Registo, number> = { id: 1, idade: 30 };
console.log(numeros.idade); // 30

const comNome: ApenasDoTipo<Registo, number> = {
  id: 1,
  idade: 30,
  // @ts-expect-error nome foi filtrado pelo remapeamento: a chave já não existe
  nome: "Ana",
};
console.log(comNome.id); // 1

const semIdentificacao: SemEstas<Registo, "id" | "ativo"> = { nome: "Ana", idade: 30 };
console.log(semIdentificacao.nome); // Ana

// @ts-expect-error a chave ativo foi removida e já não é aceite
const comAtivo: SemEstas<Registo, "id" | "ativo"> = { nome: "Rui", idade: 40, ativo: true };
console.log(comAtivo.idade); // 40

interface Artigo {
  readonly id: number;
  titulo: string;
  corpo: string;
  publicado: boolean;
  visitas: number;
}

type Campo<V> = { valor: V; erro?: string; tocado: boolean };
type Formulario<T> = { -readonly [K in keyof T]-?: Campo<T[K]> };
type Atualizacao<T> = { [K in keyof T as K extends "id" ? never : K]?: T[K] };

const form: Formulario<Artigo> = {
  id: { valor: 0, tocado: false },
  titulo: { valor: "", tocado: false },
  corpo: { valor: "", tocado: false },
  publicado: { valor: false, tocado: false },
  visitas: { valor: 0, tocado: false },
};
form.id.valor = 7;
console.log(form.id.valor); // 7

function atualizar(artigo: Artigo, mudancas: Atualizacao<Artigo>): Artigo {
  return { ...artigo, ...mudancas };
}

const original: Artigo = { id: 1, titulo: "Mapped Types", corpo: "texto", publicado: false, visitas: 0 };
const novo = atualizar(original, { publicado: true, visitas: 10 });
console.log(novo.titulo, novo.publicado, novo.visitas); // Mapped Types true 10

// @ts-expect-error id foi removido do tipo de atualização e não pode ser alterado
atualizar(original, { id: 99 });

