type Dicionario<K extends PropertyKey, V> = { [P in K]: V };

type Estado = "pendente" | "enviado" | "entregue";
type Mensagens = Dicionario<Estado, string>;

const mensagens: Mensagens = {
  pendente: "À espera de processamento",
  enviado: "A caminho",
  entregue: "Entregue ao destinatário",
};

function descrever(estado: Estado): string {
  return mensagens[estado];
}

console.log(descrever("enviado")); // A caminho
console.log(descrever("entregue")); // Entregue ao destinatário

// @ts-expect-error falta a chave entregue, que o dicionário torna obrigatória
const incompleto: Mensagens = { pendente: "à espera", enviado: "a caminho" };
console.log(incompleto.pendente); // à espera

interface Definicao {
  readonly chave: string;
  valor: number;
  descricao?: string;
}

type TudoOpcional<T> = { [K in keyof T]?: T[K] };
type TudoObrigatorio<T> = { [K in keyof T]-?: T[K] };
type TudoSoLeitura<T> = { readonly [K in keyof T]: T[K] };
type TudoEscrevivel<T> = { -readonly [K in keyof T]: T[K] };

const bloqueada: TudoSoLeitura<Definicao> = { chave: "limite", valor: 10 };
// @ts-expect-error o readonly acrescentado a todas as propriedades impede a escrita
bloqueada.valor = 20;
console.log(bloqueada.valor); // 20: readonly existe só em tempo de compilação

const aberta: TudoEscrevivel<Definicao> = { chave: "limite", valor: 10 };
aberta.chave = "teto";
console.log(aberta.chave); // teto

const rascunho: TudoOpcional<Definicao> = {};
console.log(rascunho.valor); // undefined

// @ts-expect-error com -? a descricao deixou de ser opcional
const completa: TudoObrigatorio<Definicao> = { chave: "limite", valor: 10 };
console.log(completa.valor); // 10

type EmArray<T> = { [K in keyof T]: T[K][] };

interface Leitura {
  readonly sensor: string;
  celsius: number;
}

function emListas<T extends object>(objeto: T): EmArray<T> {
  const saida = {} as EmArray<T>;
  for (const chave of Object.keys(objeto) as Array<keyof T>) {
    saida[chave] = [objeto[chave]];
  }
  return saida;
}

const listas = emListas<Leitura>({ sensor: "A1", celsius: 21.5 });
console.log(listas.sensor, listas.celsius); // [ 'A1' ] [ 21.5 ]

// @ts-expect-error o mapeamento homomórfico preservou o readonly de sensor
listas.sensor = ["B2"];

const tuplo: EmArray<[number, string]> = [[1, 2], ["a"]];
const comprimento: 2 = tuplo.length;
console.log(comprimento); // 2

interface Encomenda {
  readonly numero: number;
  cliente: string;
  total: number;
  entregue: boolean;
  notas?: string;
}

type ApenasDoTipo<T, V> = { [K in keyof T as T[K] extends V ? K : never]: T[K] };
type Editavel<T> = { -readonly [K in keyof T as K extends "numero" ? never : K]?: T[K] };

const valores: ApenasDoTipo<Encomenda, number> = { numero: 1, total: 99.5 };
console.log(valores.total); // 99.5

// @ts-expect-error cliente é string e foi filtrado pelo remapeamento
const errado: ApenasDoTipo<Encomenda, number> = { numero: 1, total: 99.5, cliente: "Ana" };
console.log(errado.numero); // 1

function aplicar(encomenda: Encomenda, alteracoes: Editavel<Encomenda>): Encomenda {
  return { ...encomenda, ...alteracoes };
}

const antes: Encomenda = { numero: 7, cliente: "Ana", total: 99.5, entregue: false };
const depois = aplicar(antes, { entregue: true, notas: "deixar na portaria" });
console.log(depois.numero, depois.entregue, depois.notas); // 7 true deixar na portaria

// @ts-expect-error numero foi removido de Editavel e não pode ser alterado
aplicar(antes, { numero: 8 });
